<?php
require_once __DIR__.'/admin-auth.php';require_once __DIR__.'/conexao.php';require_once __DIR__.'/publishing_service.php';$c=(new Database)->conectar();$s=$c->prepare('SELECT 1 FROM admin WHERE id_admin=?');$s->execute([(int)$_SESSION['id_admin']]);if(!$s->fetchColumn()){http_response_code(403);exit('Acesso administrativo inválido.');}$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$id=(int)($_POST['id_livro']??0);$action=$_POST['acao']??'';$reason=trim((string)($_POST['motivo']??''));if(!in_array($action,['retirar','restaurar'],true)||mb_strlen($reason)<10||mb_strlen($reason)>2000)throw new InvalidArgumentException('Registre um motivo de 10 a 2.000 caracteres.');
  $c->beginTransaction();$s=$c->prepare('SELECT * FROM publicacao_obra WHERE id_livro=? FOR UPDATE');$s->execute([$id]);$p=$s->fetch();if(!$p)throw new InvalidArgumentException('Obra não encontrada.');
  if($action==='retirar'){$c->prepare('UPDATE publicacao_obra SET retirado_em=now(),motivo_retirada=?,revisao=revisao+1 WHERE id_livro=?')->execute([$reason,$id]);$c->prepare("UPDATE livro SET visibilidade='privado' WHERE id_livro=?")->execute([$id]);}
  else{$c->prepare('UPDATE publicacao_obra SET retirado_em=NULL,motivo_retirada=NULL,revisao=revisao+1 WHERE id_livro=?')->execute([$id]);if($p['estado']==='publicado'&&$p['id_versao_atual'])$c->prepare("UPDATE livro SET visibilidade='publico' WHERE id_livro=?")->execute([$id]);}
  $c->prepare('INSERT INTO moderacao_obra(id_livro,id_admin,acao,motivo) VALUES(?,?,?,?)')->execute([$id,$_SESSION['id_admin'],$action,$reason]);$c->prepare("UPDATE denuncia_obra SET estado='resolvida' WHERE id_livro=?")->execute([$id]);$c->commit();$success='Decisão registrada. A disponibilidade da obra foi atualizada.';
 }catch(Throwable $e){if($c->inTransaction())$c->rollBack();$error=$e instanceof InvalidArgumentException?$e->getMessage():'Não foi possível registrar a decisão.';}
}
$reports=$c->query("SELECT d.*,u.username,l.titulo_livro,p.retirado_em FROM denuncia_obra d JOIN usuario u USING(id_user) JOIN livro l USING(id_livro) JOIN publicacao_obra p USING(id_livro) ORDER BY (d.estado='aberta') DESC,d.criada_em DESC LIMIT 100")->fetchAll();$removed=$c->query('SELECT p.id_livro,p.titulo,p.motivo_retirada FROM publicacao_obra p WHERE retirado_em IS NOT NULL ORDER BY retirado_em DESC')->fetchAll();
?><!doctype html><html lang="pt-BR"><head>
<link rel="icon" href="/TCC-Nook/img/icons/ico-nook/ico-nook.ico" type="image/x-icon"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link href="https://fonts.googleapis.com/css2?family=Lora:wght@400;500;600&amp;family=Manrope:wght@400;500;600;700&amp;display=swap" rel="stylesheet"><title>Moderação de obras | Nook</title><link rel="stylesheet" href="../front-end/css/core.css"><link rel="stylesheet" href="../front-end/css/pages/publishing.css"><script src="../front-end/js/pages/moderacao-obras.js" defer></script></head><body><main class="writing-page"><p class="writing-eyebrow">ADMINISTRAÇÃO</p><h1>Denúncias de obras</h1><a href="crud_autores.php">Voltar à administração</a><p role="alert"><?=eObra($error)?></p><p role="status"><?=eObra($success)?></p><section class="writing-comments"><?php foreach($reports as $report):?><article><h2><?=eObra($report['titulo_livro'])?></h2><p><?=eObra($report['motivo'])?> · <?=eObra($report['estado'])?> · @<?=eObra($report['username'])?></p><p><?=nl2br(eObra($report['detalhes']))?></p><a href="leitor_obra.php?id_livro=<?=(int)$report['id_livro']?>">Ver publicação</a><form method="post" data-moderation-confirm><input type="hidden" name="csrf_token" value="<?=eObra($_SESSION['admin_csrf_token'])?>"><input type="hidden" name="id_livro" value="<?=(int)$report['id_livro']?>"><label>Decisão<select name="acao"><option value="retirar">Retirar do ar</option><option value="restaurar">Restaurar disponibilidade</option></select></label><label>Justificativa<textarea name="motivo" minlength="10" maxlength="2000" required rows="3"></textarea></label><button class="writing-primary">Registrar decisão</button></form></article><?php endforeach;?><?php if(!$reports):?><p>Nenhuma denúncia registrada.</p><?php endif;?></section><section class="writing-comments"><h2>Obras retiradas</h2><?php foreach($removed as $r):?><article><h3><?=eObra($r['titulo'])?></h3><p><?=eObra($r['motivo_retirada'])?></p><form method="post" data-moderation-confirm><input type="hidden" name="csrf_token" value="<?=eObra($_SESSION['admin_csrf_token'])?>"><input type="hidden" name="id_livro" value="<?=(int)$r['id_livro']?>"><input type="hidden" name="acao" value="restaurar"><label>Justificativa para restaurar<textarea name="motivo" minlength="10" maxlength="2000" required rows="2"></textarea></label><button class="writing-secondary">Restaurar</button></form></article><?php endforeach;?></section></main></body></html>
